#include "stdlib/integrate/strided/dtrapezoid.h"
#include "stdlib/blas/base/shared.h"
#include "stdlib/strided/base/stride2offset.h"

static const CBLAS_INT M = 5;

/**
* Computes the integral of a double-precision floating-point strided array using the trapezoidal rule.
*
* @param N        number of indexed elements
* @param X        first array
* @param strideX  stride length for X
* @param Y        second array
* @param strideY  stride length for Y
* @return         integral approximation
*/
double API_SUFFIX(stdlib_strided_dtrapezoid)( const CBLAS_INT N, const double *X, const CBLAS_INT strideX, const double *Y, const CBLAS_INT strideY ) {
	CBLAS_INT ox = stdlib_strided_stride2offset( N, strideX );
	CBLAS_INT oy = stdlib_strided_stride2offset( N, strideY );
	return API_SUFFIX(stdlib_strided_dtrapezoid_ndarray)( N, X, strideX, ox, Y, strideY, oy );
}

/**
* Computes the integral of a double-precision floating-point strided array using the trapezoidal rule and alternative indexing semantics.
*
* @param N        number of indexed elements
* @param X        first array
* @param strideX  stride length for X
* @param offsetX  starting index for X
* @param Y        second array
* @param strideY  stride length for Y
* @param offsetY  starting index for Y
* @return         integral approximation
*/
double API_SUFFIX(stdlib_strided_dtrapezoid_ndarray)( const CBLAS_INT N, const double *X, const CBLAS_INT strideX, const CBLAS_INT offsetX, const double *Y, const CBLAS_INT strideY, const CBLAS_INT offsetY ) {
	CBLAS_INT ix;
	CBLAS_INT iy;
	CBLAS_INT m;
	CBLAS_INT i;
	double sum;
	double x0;
	double x1;
	double y0;
	double y1;

	sum = 0.0;
	if ( N <= 1 ) {
		return sum;
	}
	ix = offsetX;
	iy = offsetY;

	// If both strides are equal to `1`, use unrolled loops...
	if ( strideX == 1 && strideY == 1 ) {
		m = (N - 1) % M;
		if ( m > 0 ) {
			for ( i = 0; i < m; i++ ) {
				sum += ((X[ix+1] - X[ix]) * (Y[iy] + Y[iy+1]));
				ix += 1;
				iy += 1;
			}
		}
		if ( N - 1 < M ) {
			return sum * 0.5;
		}
		for ( i = m; i < N - 1; i += M ) {
			sum += (((X[ix+1]-X[ix])*(Y[iy]+Y[iy+1])) +
				((X[ix+2]-X[ix+1])*(Y[iy+1]+Y[iy+2])) +
				((X[ix+3]-X[ix+2])*(Y[iy+2]+Y[iy+3])) +
				((X[ix+4]-X[ix+3])*(Y[iy+3]+Y[iy+4])) +
				((X[ix+5]-X[ix+4])*(Y[iy+4]+Y[iy+5])));
			ix += M;
			iy += M;
		}
		return sum * 0.5;
	}
	x0 = X[ix];
	y0 = Y[iy];
	for ( i = 1; i < N; i++ ) {
		ix += strideX;
		iy += strideY;
		x1 = X[ix];
		y1 = Y[iy];
		sum += ((x1 - x0) * (y1 + y0));
		x0 = x1;
		y0 = y1;
	}
	return sum * 0.5;
}
